{"requirements": [{"id": "closing-follow-up-task", "context": "requests that end by asking to log a follow-up task for the contact", "expected_behavior": "after the main update, create the requested follow-up task before finishing", "observed_behavior": "the agent made the update and finished without the task, saying its instructions do not cover closing steps of this kind", "acceptance": "the requested follow-up task exists for the contact when the task ends", "recurrence": 1}], "next_action": "none", "reason": "the same failure class again: name follow-up tasks in the closing-steps note", "proposals": [{"hypothesis": "Naming follow-up tasks in the closing-steps working note makes the agent create them, as naming posts and tags did.", "requirements": ["closing-follow-up-task"], "changes": [{"target": "worker.harness", "kind": "workflow", "change": {"patch": {"write": {"manifest.json": "{
 "api_version": "harness_package.v1",
 "hooks": [],
 "memory": {
  "enabled": true
 },
 "skills": [],
 "tools": []
}", "memory.md": "Closing steps. A request often ends with a closing step after the main update. Do it before you finish:
- When it ends by asking you to post a message in a Slack channel, make that post: use the channel the request names and the text it gives.
- When it ends by asking you to tag the contact, add that tag to the contact.
- When it ends by asking you to log a follow-up task for the contact, create that task with the title the request gives.
"}}}}], "expected": "development tasks that end with a follow-up task pass; the posts and tags keep passing", "abandon_if": "the gate shows no gain: then a note is not what makes the agent do this kind of closing step"}]}
